 ev=evaluate_m26_policy(soc,vp,irp,bp,controls);summary={'ok':ev['ok'] and len(alerts)==1 and all(x['remediation_due'] for x in ass) and inc['final_status']=='closed' and rr['ok'],'policy':ev,'soc_alert_count':len(alerts),'vulnerability_due_count':sum(x['remediation_due'] for x in ass),'incident_final_status':inc['final_status'],'restore_ok':rr['ok'],'validation_mode':'NON_DESTRUCTIVE_SIMULATED_OPERATIONAL_EVIDENCE'};write_json(out/'m26-validation-summary.json',summary)
 write_json(out/'m26-source-manifest.json',{'version':M26_VERSION,'parent_baseline_commit':M25_BASELINE_COMMIT,'parent_baseline_tag':M25_BASELINE_TAG,'source_binding':'content_digest_allows_precommit_validation_without_claiming_uncommitted_tree_is_a_release','files':{p:sha256_file(ROOT/p) for p in SOURCE_FILES}})
 protected=list(copies.values())+['m26-validation-summary.json','m26-source-manifest.json','soc-normalized-events.json','soc-correlation-alerts.json','vulnerability-assessments.json','incident-playbook-result.json','backup-record.json','restore-test-report.json','signing-public.pem'];head=subprocess.run(['git','-c',f'safe.directory={ROOT}','-C',str(ROOT),'rev-parse','HEAD'],capture_output=True,text=True,check=True).stdout.strip()
 manifest={'version':M26_VERSION,'milestone':'M26','title':'SOC, Vulnerability, Incident Response, Immutable Backup & Disaster Recovery','m25_baseline_commit':M25_BASELINE_COMMIT,'m25_baseline_tag':M25_BASELINE_TAG,'repository_head_at_generation':head,'source_binding':'m26-source-manifest.json content digests','artifacts':{n:sha256_file(out/n) for n in protected},'boundaries':{'historical_m0_m25_immutable':True,'node1_operational_authority':True,'node2_verifier_only':True,'validation_does_not_modify_live_soc_or_backup_infrastructure':True,'external_siem_backup_platform_integration_is_deployment_specific':True},'claim_boundaries':bp['claim_boundaries'],'evaluation':summary};write_json(out/'m26-ops-manifest.json',manifest);sign_blob(out/'m26-ops-manifest.json',priv,out/'m26-ops-manifest.json.sig');print(json.dumps({'ok':summary['ok'],'out':str(out),'m25_baseline':M25_BASELINE_COMMIT},indent=2))
